from datetime import date

from django.db import migrations, models


def move_health_data(apps, schema_editor):
    """Body data and the daily goal moved to tracking; keep what was consented to."""
    Profile = apps.get_model("accounts", "Profile")
    BodyData = apps.get_model("tracking", "BodyData")
    DailyGoal = apps.get_model("tracking", "DailyGoal")

    for profile in Profile.objects.filter(data_consent=True):
        if profile.date_of_birth:
            today = date.today()
            born = profile.date_of_birth
            age = today.year - born.year - ((today.month, today.day) < (born.month, born.day))
        else:
            today = age = None

        BodyData.objects.update_or_create(
            owner_id=profile.user_id,
            defaults={
                "sex": profile.sex or "",
                "age": age,
                "age_given_on": today,
                "height": profile.height,
                "goal": profile.goal or "",
            },
        )

        if profile.target_calories:
            granted = profile.data_consent_date_granted

            DailyGoal.objects.update_or_create(
                owner_id=profile.user_id,
                valid_from=granted.date() if granted else date.today(),
                defaults={
                    "source": "berechnet",
                    "kcal": profile.target_calories,
                    "protein": profile.target_protein or 0,
                    "carbs": profile.target_carbs or 0,
                    "fat": profile.target_fat or 0,
                    "weight": profile.weight,
                },
            )


